        refreshPanelPlayers();
    }

    private boolean importMissingNativeIgnores()
    {
        return importMissingNativeIgnores(false);
    }

    private boolean importMissingNativeIgnores(boolean newNativeEntriesOnly)
    {
        NameableContainer<Ignore> ignoreContainer = client.getIgnoreContainer();
        if (ignoreContainer == null)
        {
            return false;
        }

        Ignore[] members = ignoreContainer.getMembers();
        if (members == null || members.length == 0)
        {
            return false;
        }

        List<Ignore> legacyOrderedMembers = new ArrayList<>();
        for (Ignore member : members)
        {
            if (member != null)
            {
                legacyOrderedMembers.add(member);
            }
        }
        // Ignore's natural comparison uses native insertion order, not the active UI sort.
        legacyOrderedMembers.sort(Comparator.reverseOrder());

        boolean changed = false;
        Map<String, IgnoredPlayer> importedPlayers = new LinkedHashMap<>();
        for (Ignore member : legacyOrderedMembers)
        {
            String currentName = member.getName();
            if (currentName == null || currentName.isEmpty())
            {
                continue;
            }

            String previousName = member.getPrevName();
            if (newNativeEntriesOnly)
            {
                String normalizedCurrentName = normalizeName(currentName);
                String normalizedPreviousName = normalizeName(previousName);
                if (nativeIgnoreNamesSyncedDuringAddAttempt.contains(normalizedCurrentName)
                    || nativeIgnoreNamesSyncedDuringAddAttempt.contains(normalizedPreviousName))
                {
                    continue;
                }
                nativeIgnoreNamesSyncedDuringAddAttempt.add(normalizedCurrentName);
                if (normalizedPreviousName != null)
                {
                    nativeIgnoreNamesSyncedDuringAddAttempt.add(normalizedPreviousName);
                }
            }

            IgnoredPlayer ignoredPlayer = findIgnoredPlayerByName(currentName);
            if (ignoredPlayer == null)
            {
                ignoredPlayer = new IgnoredPlayer(currentName);
                ignoredPlayers.put(normalizeName(currentName), ignoredPlayer);
                importedPlayers.put(normalizeName(currentName), ignoredPlayer);
                changed = true;
            }

            if (previousName != null && !previousName.isEmpty())
            {
                int aliasesBefore = ignoredPlayer.getAliases().size();
                ignoredPlayer.addAlias(previousName);
                changed |= aliasesBefore != ignoredPlayer.getAliases().size();
            }
            changed |= copyFriendNote(ignoredPlayer, previousName);
        }

        if (!importedPlayers.isEmpty())
        {
            long addedAt = nextAddedAt() + importedPlayers.size() - 1;
            for (IgnoredPlayer player : importedPlayers.values())
            {
                player.setAddedAt(addedAt--);
            }
            importedPlayers.putAll(ignoredPlayers);
            ignoredPlayers.clear();
            ignoredPlayers.putAll(importedPlayers);
        }

        if (changed)
        {
            nativeIgnoreFingerprint = null;
            persistIgnoredPlayers();
        }

        return changed;
    }

    private boolean copyFriendNote(IgnoredPlayer player, String previousName)
    {
        if (!player.getNote().isEmpty())
        {
            return false;
        }

        String note = findFriendNote(player, previousName);
        if (note == null)
        {
            return false;
        }
        player.setNote(note);
        return true;
    }

    private String findFriendNote(IgnoredPlayer player, String previousName)
    {
        Set<String> names = new LinkedHashSet<>();
        names.add(player.getCurrentName());
        if (previousName != null && !previousName.isEmpty())
        {
            names.add(previousName);
        }
        names.addAll(player.getAliases());
        for (String name : names)
        {
            String note = configManager.getConfiguration(FRIEND_NOTES_CONFIG_GROUP,
                FRIEND_NOTES_KEY_PREFIX + Text.toJagexName(name));
            if (note != null && !note.isEmpty())
            {
                return note;
            }
        }
        return null;
    }

    private String findNativePreviousName(IgnoredPlayer player)
    {
        NameableContainer<Ignore> container = client.getIgnoreContainer();
        if (container != null && container.getMembers() != null)
        {
            for (Ignore member : container.getMembers())
            {
                if (member != null && matchesAnyTrackedName(player, member.getName(), member.getPrevName()))
                {
                    return member.getPrevName();
                }
            }
        }
        return null;
    }

