package com.extendedignorelist;

import java.util.Comparator;
import net.runelite.client.util.Text;

public enum IgnoreListSortOrder
{
    NAME_ASCENDING("Name A-Z"),
    NAME_DESCENDING("Name Z-A"),
    OLDEST_FIRST("Oldest first"),
    NEWEST_FIRST("Newest first");

    private final String label;

    IgnoreListSortOrder(String label)
    {
        this.label = label;
    }

    public Comparator<IgnoredPlayer> comparator()
    {
        Comparator<IgnoredPlayer> byName = Comparator.comparing(
            player -> Text.standardize(player.getCurrentName()));
        Comparator<IgnoredPlayer> byDate = Comparator.comparingLong(IgnoredPlayer::getAddedAt);
        switch (this)
        {
            case NAME_ASCENDING:
                return byName.thenComparing(byDate);
            case NAME_DESCENDING:
                return byName.reversed().thenComparing(byDate);
            case OLDEST_FIRST:
                return byDate.thenComparing(byName);
            case NEWEST_FIRST:
                return byDate.reversed().thenComparing(byName);
            default:
                throw new IllegalStateException("Unsupported ignore list sort order: " + this);
        }
    }

    @Override
    public String toString()
    {
        return label;
    }
}

package com.extendedignorelist;

import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashSet;
import java.util.List;

public class IgnoredPlayer
{
    private String currentName;
    private String note = "";
    private long addedAt;
    private final LinkedHashSet<String> aliases = new LinkedHashSet<>();

    public IgnoredPlayer(String currentName)
    {
        this.currentName = currentName;
    }

    public IgnoredPlayer(String currentName, Collection<String> aliases)
    {
        this.currentName = currentName;
        addAliases(aliases);
    }

    public IgnoredPlayer(String currentName, Collection<String> aliases, String note)
    {
        this(currentName, aliases);
        setNote(note);
    }

    public String getCurrentName()
    {
        return currentName;
    }

    public void setCurrentName(String currentName)
    {
        this.currentName = currentName;
    }

    public long getAddedAt()
    {
        return addedAt;
    }

    void setAddedAt(long addedAt)
    {
        this.addedAt = addedAt;
    }

    public String getNote()
    {
        return note;
    }

    public void setNote(String note)
    {
        this.note = note == null ? "" : note;
    }

    public List<String> getAliases()
    {
        return new ArrayList<>(aliases);
    }

    public void addAlias(String alias)
    {
        if (alias == null || alias.isEmpty() || alias.equals(currentName))
        {
            return;
        }

        aliases.add(alias);
    }

    public void addAliases(Collection<String> aliases)
    {
        if (aliases == null)
        {
            return;
        }

        for (String alias : aliases)
        {
            addAlias(alias);
        }
    }
}

package com.extendedignorelist;

import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.Iterator;
import java.util.Map;
import java.util.Set;
import java.util.function.Predicate;
import java.util.regex.Pattern;
import net.runelite.api.Client;
