import net.runelite.api.widgets.WidgetType;
import net.runelite.client.util.Text;

final class RaidBoardHighlighter
{
    // These Archive HUD scripts do not yet have RuneLite ScriptID constants.
    private static final int ARCHIVE_HUD_INIT_SCRIPT = 10031;
    private static final int ARCHIVE_HUD_UPDATE_SCRIPT = 10033;
    private static final int[] PLAYER_LIST_COMPONENTS = {
        InterfaceID.RaidsLobbyPartylist.LIST,
        InterfaceID.RaidsLobbyPartydetails.LIST,
        InterfaceID.RaidsSidepanel.LIST,
        InterfaceID.TobPartylist.LIST,
        InterfaceID.TobPartydetails.CURRENT,
        InterfaceID.TobPartydetails.APPLICANTS,
        InterfaceID.TobHud.NAMES,
        InterfaceID.ToaPartylist.LIST,
        InterfaceID.ToaPartydetails.MEMBERS_LIST,
        InterfaceID.ToaPartydetails.APPLICANTS_LIST,
        InterfaceID.ToaLobby.NAMES,
        InterfaceID.TfaPartylist.LIST,
        InterfaceID.TfaPartydetails.MEMBERS_LIST,
        InterfaceID.TfaPartydetails.APPLICANTS_LIST,
        InterfaceID.TfaLobby.NAMES,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_LEADER_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_1_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_2_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_3_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_4_NAME,
        InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN1,
        InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN2,
        InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN3,
        InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN4,
        InterfaceID.BarbassaultScrollPl1.BARBASSAULT_SCROLL_PL1_TN5,
        InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN1,
        InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN2,
        InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN3,
        InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN4,
        InterfaceID.BarbassaultScrollPl2.BARBASSAULT_SCROLL_PL2_TN5
    };
    private static final int[] ARCHIVE_HUD_CONTAINERS = {
        InterfaceID.TfaHud._0_CONTAINER, InterfaceID.TfaHud._1_CONTAINER,
        InterfaceID.TfaHud._2_CONTAINER, InterfaceID.TfaHud._3_CONTAINER,
        InterfaceID.TfaHud._4_CONTAINER, InterfaceID.TfaHud._5_CONTAINER,
        InterfaceID.TfaHud._6_CONTAINER, InterfaceID.TfaHud._7_CONTAINER
    };
    private static final Pattern COLOR_TAGS = Pattern.compile("</?col(?:=[^>]*)?>", Pattern.CASE_INSENSITIVE);
    private static final String RED_PREFIX = "<col=ff0000>";

    private final Client client;
    private final Predicate<String> isIgnoredName;
    private final Map<Widget, Highlight> highlights = new IdentityHashMap<>();

    RaidBoardHighlighter(Client client, Predicate<String> isIgnoredName)
    {
        this.client = client;
        this.isIgnoredName = isIgnoredName;
    }

    void onScriptPostFired(int scriptId, boolean enabled)
    {
        if (scriptId == ARCHIVE_HUD_INIT_SCRIPT || scriptId == ARCHIVE_HUD_UPDATE_SCRIPT)
        {
            refresh(enabled);
        }
    }

    void refresh(boolean enabled)
    {
        if (!enabled)
        {
            restore();
            return;
        }

        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        for (int componentId : PLAYER_LIST_COMPONENTS)
        {
            Widget widget = client.getWidget(componentId);
            if (componentId == InterfaceID.RaidsSidepanel.LIST)
            {
                highlightChambersNames(widget, visited);
            }
            highlight(widget, visited);
        }
        highlightArchiveNames(visited);

        Iterator<Map.Entry<Widget, Highlight>> iterator = highlights.entrySet().iterator();
        while (iterator.hasNext())
        {
            Map.Entry<Widget, Highlight> entry = iterator.next();
            if (!visited.contains(entry.getKey()))
            {
                restore(entry.getKey(), entry.getValue());
                iterator.remove();
            }
        }
    }

    void restore()
    {
        highlights.forEach(this::restore);
        highlights.clear();
    }

    private void highlight(Widget widget, Set<Widget> visited)
    {
        if (widget == null || widget.isHidden() || !visited.add(widget))
        {
            return;
        }

        if (widget.getType() == WidgetType.TEXT)
        {
            highlightName(widget);
        }

        highlightChildren(widget.getStaticChildren(), visited);
        highlightChildren(widget.getDynamicChildren(), visited);
        highlightChildren(widget.getNestedChildren(), visited);
    }

    private void highlightChildren(Widget[] children, Set<Widget> visited)
    {
        if (children != null)
        {
            for (Widget child : children)
            {
                highlight(child, visited);
            }
        }
    }

    private void highlightName(Widget widget)
    {
        highlightName(widget, null);
    }

    private void highlightChambersNames(Widget list, Set<Widget> visited)
    {
        if (list == null || list.isHidden() || list.getDynamicChildren() == null)
        {
            return;
        }
        Widget[] children = list.getDynamicChildren();
        for (int row = 0; row + RaidPartyRoster.CHAMBERS_FULL_NAME_OFFSET < children.length;
            row += RaidPartyRoster.CHAMBERS_ROW_SIZE)
        {
            Widget visibleName = children[row + RaidPartyRoster.CHAMBERS_VISIBLE_NAME_OFFSET];
            Widget fullName = children[row + RaidPartyRoster.CHAMBERS_FULL_NAME_OFFSET];
            if (visibleName != null && fullName != null && fullName.getText() != null
                && !visibleName.isHidden() && visibleName.getType() == WidgetType.TEXT
                && visited.add(visibleName))
            {
                // The visible label may be truncated; the hidden sort field retains the full name.
                highlightName(visibleName, Text.removeTags(fullName.getText()));
            }
        }
    }

    private void highlightArchiveNames(Set<Widget> visited)
    {
        Widget names = client.getWidget(InterfaceID.TfaHud.CONTENT_NAMES);
        if (names == null || names.isHidden())
        {
            return;
        }
        for (int i = 0; i < ARCHIVE_HUD_CONTAINERS.length; i++)
        {
            Widget container = client.getWidget(ARCHIVE_HUD_CONTAINERS[i]);
            if (container == null || container.isHidden()
                || client.getVarbitValue(RaidPartyRoster.ARCHIVE_MEMBERS[i]) == 0)
            {
                continue;
            }
            Widget label = container.getChild(0);
            String fullName = client.getVarcStrValue(RaidPartyRoster.ARCHIVE_NAMES[i]);
            if (label != null && !label.isHidden() && label.getType() == WidgetType.TEXT
                && fullName != null && !fullName.isEmpty() && !"null".equalsIgnoreCase(fullName)
                && visited.add(label))
            {
                // Archive HUD labels are initials; match against the full name in the corresponding slot.
                highlightName(label, Text.removeTags(fullName));
            }
        }
    }

    private void highlightName(Widget widget, String fullName)
    {
        String displayedText = widget.getText();
        Highlight previous = highlights.get(widget);
        String originalText = displayedText;
        if (previous != null)
        {
            if (previous.coloredText.equals(displayedText))
            {
                originalText = previous.originalText;
            }
            else
            {
                // Game scripts can reuse the same row for a different player.
                highlights.remove(widget);
                previous = null;
            }
        }

        if (originalText == null || originalText.isEmpty())
        {
            if (previous != null)
            {
                restore(widget, previous);
                highlights.remove(widget);
            }
            return;
        }

        String coloredText = originalText;
        if (widget.getId() == InterfaceID.TobHud.NAMES
            || widget.getId() == InterfaceID.ToaLobby.NAMES
            || widget.getId() == InterfaceID.TfaLobby.NAMES)
        {
            String[] lines = originalText.split("(?i)(?<=<br>)|(?<=\\n)", -1);
            StringBuilder coloredLines = new StringBuilder();
            for (String line : lines)
            {
                String separator = "";
                String name = line;
                if (line.toLowerCase(java.util.Locale.ROOT).endsWith("<br>"))
                {
                    separator = line.substring(line.length() - 4);
                    name = line.substring(0, line.length() - 4);
                }
                else if (line.endsWith("\n"))
                {
                    separator = "\n";
                    name = line.substring(0, line.length() - 1);
                }
                coloredLines.append(isIgnoredName.test(Text.removeTags(name).trim())
                    ? RED_PREFIX + COLOR_TAGS.matcher(name).replaceAll("") + "</col>" : name);
                coloredLines.append(separator);
            }
            coloredText = coloredLines.toString();
        }
        else if (isIgnoredName.test(fullName == null ? Text.removeTags(originalText) : fullName))
        {
            coloredText = RED_PREFIX + COLOR_TAGS.matcher(originalText).replaceAll("") + "</col>";
        }
        if (coloredText.equals(originalText))
        {
            if (previous != null)
            {
                restore(widget, previous);
                highlights.remove(widget);
            }
            return;
        }
        if (!coloredText.equals(displayedText))
        {
            widget.setText(coloredText);
        }
        if (previous == null && !coloredText.equals(originalText))
        {
            highlights.put(widget, new Highlight(originalText, coloredText));
        }
    }

    private void restore(Widget widget, Highlight highlight)
    {
        // Do not overwrite text changed by the game or another plugin.
        if (highlight.coloredText.equals(widget.getText()))
        {
            widget.setText(highlight.originalText);
        }
    }

    private static final class Highlight
    {
        private final String originalText;
        private final String coloredText;

        private Highlight(String originalText, String coloredText)
        {
            this.originalText = originalText;
            this.coloredText = coloredText;
        }
    }
}

package com.extendedignorelist;

import java.util.ArrayList;
import java.util.EnumMap;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.function.BooleanSupplier;
import java.util.function.Predicate;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.FriendsChatManager;
import net.runelite.api.FriendsChatMember;
import net.runelite.api.Player;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.Text;

final class RaidGroupMonitor
{
    private static final int[] TOB_NAMES = {
        VarClientID.TOB_CLIENT_NAME0, VarClientID.TOB_CLIENT_NAME1,
        VarClientID.TOB_CLIENT_NAME2, VarClientID.TOB_CLIENT_NAME3, VarClientID.TOB_CLIENT_NAME4
    };
    private static final int[] TOB_MEMBERS = {
        VarbitID.TOB_CLIENT_P0, VarbitID.TOB_CLIENT_P1,
        VarbitID.TOB_CLIENT_P2, VarbitID.TOB_CLIENT_P3, VarbitID.TOB_CLIENT_P4
    };
    private static final int[] TOA_NAMES = {
        VarClientID.TOA_CLIENT_NAME0, VarClientID.TOA_CLIENT_NAME1,
        VarClientID.TOA_CLIENT_NAME2, VarClientID.TOA_CLIENT_NAME3,
        VarClientID.TOA_CLIENT_NAME4, VarClientID.TOA_CLIENT_NAME5,
        VarClientID.TOA_CLIENT_NAME6, VarClientID.TOA_CLIENT_NAME7
    };
    private static final int[] TOA_MEMBERS = {
        VarbitID.TOA_CLIENT_P0, VarbitID.TOA_CLIENT_P1,
        VarbitID.TOA_CLIENT_P2, VarbitID.TOA_CLIENT_P3,
        VarbitID.TOA_CLIENT_P4, VarbitID.TOA_CLIENT_P5,
        VarbitID.TOA_CLIENT_P6, VarbitID.TOA_CLIENT_P7
    };
    private static final int BA_LOBBY_REGION_ID = 10322;
    private static final int COX_ENTRANCE_REGION_ID = 4919;
    private static final int[] BA_TEAM_NAMES = {
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_LEADER_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_1_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_2_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_3_NAME,
        InterfaceID.BarbassaultOverRecruitPlayerNames.BARBASSAULT_PLAYER_4_NAME
    };

    private final Client client;
    private final Predicate<String> isIgnoredName;
    private final BooleanSupplier censorName;
    private final GroupAlertConsumer notify;
    private final Map<Raid, Set<String>> previousMatches = new EnumMap<>(Raid.class);

    RaidGroupMonitor(Client client, Predicate<String> isIgnoredName,
        BooleanSupplier censorName,
        GroupAlertConsumer notify)
    {
        this.client = client;
        this.isIgnoredName = isIgnoredName;
        this.censorName = censorName;
        this.notify = notify;
    }

    void reset()
    {
        previousMatches.clear();
    }

    void refresh(GroupNotificationMode mode)
    {
        if (mode == GroupNotificationMode.NONE || client.getGameState() != GameState.LOGGED_IN)
        {
            reset();
            return;
        }

        check(Raid.TOB, readTheatreParty(), mode);
        check(Raid.TOA, readAmascutParty(), mode);
        check(Raid.COX, readChambersParty(), mode);
        check(Raid.TFA, readArchiveParty(), mode);
        check(Raid.BA, readBarbarianAssaultTeam(), mode);
    }

    private List<String> readBarbarianAssaultTeam()
    {
        List<String> team = new ArrayList<>();
        boolean rosterAvailable = false;
        for (int component : BA_TEAM_NAMES)
        {
            Widget name = client.getWidget(component);
            if (name != null && !name.isHidden())
            {
                rosterAvailable = true;
                String text = name.getText();
                if (text != null && !"-----".equals(Text.removeTags(text).trim()))
                {
                    team.add(text);
                }
            }
        }
        if (rosterAvailable)
        {
            return team;
        }

        // The recruitment roster disappears during waves; absence is not a team departure.
        Player localPlayer = client.getLocalPlayer();
        WorldPoint location = localPlayer == null ? null : localPlayer.getWorldLocation();
        if (client.getVarbitValue(VarbitID.BARBASSAULT_AREAEXIT_PENDING) == 1
            || (location != null && location.getRegionID() == BA_LOBBY_REGION_ID))
        {
            return null;
        }
        return team;
    }

    private List<String> readParty(int statusVarbit, int slotVarbit, int[] names, int[] members)
    {
        List<String> party = new ArrayList<>();
        int ownSlot = client.getVarbitValue(slotVarbit);
        if (client.getVarbitValue(statusVarbit) == 0 || ownSlot == 0)
        {
            return party;
        }

        for (int i = 0; i < names.length; i++)
        {
            if (i != ownSlot - 1 && client.getVarbitValue(members[i]) != 0)
            {
                party.add(client.getVarcStrValue(names[i]));
            }
        }
        return party;
    }

    private List<String> readTheatreParty()
    {
        int status = client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSTATUS);
        if ((status != 1 && status != 2)
            || (status == 2 && client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSLOT) == 0))
        {
            return new ArrayList<>();
        }
        List<String> hudNames = RaidPartyRoster.readNames(client.getWidget(InterfaceID.TobHud.NAMES));
        if (hudNames != null)
        {
            return hudNames;
        }
        // Lobby membership is shown by the names HUD; combat slots can still be unset.
        if (status == 1 && client.getVarbitValue(VarbitID.TOB_CLIENT_PARTYSLOT) == 0)
        {
            return null;
        }
        return readParty(VarbitID.TOB_CLIENT_PARTYSTATUS, VarbitID.TOB_CLIENT_PARTYSLOT,
            TOB_NAMES, TOB_MEMBERS);
    }

    private List<String> readAmascutParty()
    {
        int status = client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSTATUS);
        if (status != 1 && status != 2)
        {
            return new ArrayList<>();
        }
        List<String> lobbyNames = RaidPartyRoster.readNames(client.getWidget(InterfaceID.ToaLobby.NAMES));
        if (lobbyNames != null)
        {
            return lobbyNames;
        }
        if (status == 1 && client.getVarbitValue(VarbitID.TOA_CLIENT_PARTYSLOT) == 0)
        {
            return null;
        }
        return readParty(VarbitID.TOA_CLIENT_PARTYSTATUS, VarbitID.TOA_CLIENT_PARTYSLOT,
            TOA_NAMES, TOA_MEMBERS);
    }

    private List<String> readArchiveParty()
    {
        if (client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSTATUS) == 0
            || client.getVarbitValue(VarbitID.TFA_CLIENT_SPECTATE_MODE) == 2)
        {
            return new ArrayList<>();
        }
        List<String> lobbyNames = RaidPartyRoster.readNames(client.getWidget(InterfaceID.TfaLobby.NAMES));
        if (lobbyNames != null)
        {
            return lobbyNames;
        }
        if (client.getVarbitValue(VarbitID.TFA_CLIENT_PARTYSLOT) == 0)
        {
            return null;
        }
        return readParty(VarbitID.TFA_CLIENT_PARTYSTATUS, VarbitID.TFA_CLIENT_PARTYSLOT,
            RaidPartyRoster.ARCHIVE_NAMES, RaidPartyRoster.ARCHIVE_MEMBERS);
    }

    private List<String> readChambersParty()
    {
        if (client.getVarbitValue(VarbitID.RAIDS_CLIENT_INDUNGEON) == 0)
        {
            return readChambersLobbyParty();
        }

        Widget list = client.getWidget(InterfaceID.RaidsSidepanel.LIST);
        if (list == null || list.isHidden() || list.getDynamicChildren() == null)
        {
            // An unavailable sidepanel is not evidence that a player left the party.
            return null;
        }

        List<String> party = new ArrayList<>();
        Widget[] children = list.getDynamicChildren();
        for (int i = RaidPartyRoster.CHAMBERS_FULL_NAME_OFFSET; i < children.length;
            i += RaidPartyRoster.CHAMBERS_ROW_SIZE)
        {
            if (children[i] != null)
            {
                party.add(children[i].getText());
            }
        }
        return party;
    }

    private List<String> readChambersLobbyParty()
    {
        Player localPlayer = client.getLocalPlayer();
        WorldPoint location = localPlayer == null ? null : localPlayer.getWorldLocation();
        if (location == null)
        {
            return null;
        }
        if (location.getRegionID() != COX_ENTRANCE_REGION_ID)
        {
            return new ArrayList<>();
        }
        FriendsChatManager friendsChat = client.getFriendsChatManager();
        if (friendsChat == null)
        {
            return new ArrayList<>();
        }
        FriendsChatMember[] members = friendsChat.getMembers();
        if (members == null)
        {
            return null;
        }
        List<String> party = new ArrayList<>();
        for (FriendsChatMember member : members)
        {
            if (member != null)
            {
                party.add(member.getName());
            }
        }
        return party;
    }

    private void check(Raid raid, List<String> party, GroupNotificationMode mode)
    {
        if (party == null)
        {
            return;
        }

        Set<String> currentMatches = new HashSet<>();
        Set<String> previous = previousMatches.getOrDefault(raid, Set.of());
        List<String> newNames = new ArrayList<>();
        String localName = client.getLocalPlayer() == null ? null : client.getLocalPlayer().getName();
        String normalizedLocalName = localName == null ? null : Text.standardize(localName);
        for (String name : party)
        {
            if (name == null)
            {
                continue;
            }
            String cleanName = Text.removeTags(name).replace('\u00a0', ' ').trim();
            String normalizedName = Text.standardize(cleanName);
            if (cleanName.isEmpty() || "-".equals(cleanName) || "null".equalsIgnoreCase(cleanName)
                || normalizedName.equals(normalizedLocalName) || !isIgnoredName.test(cleanName))
            {
                continue;
            }
            if (currentMatches.add(normalizedName) && !previous.contains(normalizedName))
            {
                newNames.add(cleanName);
            }
        }
        previousMatches.put(raid, currentMatches);
        if (!newNames.isEmpty())
        {
            String subject = censorName.getAsBoolean()
                ? (newNames.size() == 1 ? "Someone" : "Some people")
                : String.join(", ", newNames);
            notify.accept(mode, subject
                + (newNames.size() == 1 ? " is" : " are") + " on your extended ignore list.",
                currentMatches.size() == 1 ? newNames.get(0) : null);
        }
    }

    private enum Raid
    {
        TOB,
        TOA,
        COX,
        TFA,
        BA
    }

    @FunctionalInterface
    interface GroupAlertConsumer
    {
        void accept(GroupNotificationMode mode, String message, String singleIgnoredName);
    }
}

package com.extendedignorelist;

import java.util.ArrayList;
import java.util.Collections;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.gameval.VarbitID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetType;

final class RaidPartyRoster
{
    static final int CHAMBERS_ROW_SIZE = 7;
    static final int CHAMBERS_VISIBLE_NAME_OFFSET = 1;
    static final int CHAMBERS_FULL_NAME_OFFSET = 4;
    static final int[] ARCHIVE_NAMES = {
        VarClientID.TFA_CLIENT_NAME0, VarClientID.TFA_CLIENT_NAME1,
        VarClientID.TFA_CLIENT_NAME2, VarClientID.TFA_CLIENT_NAME3,
        VarClientID.TFA_CLIENT_NAME4, VarClientID.TFA_CLIENT_NAME5,
        VarClientID.TFA_CLIENT_NAME6, VarClientID.TFA_CLIENT_NAME7
    };
    static final int[] ARCHIVE_MEMBERS = {
        VarbitID.TFA_CLIENT_P0, VarbitID.TFA_CLIENT_P1,
        VarbitID.TFA_CLIENT_P2, VarbitID.TFA_CLIENT_P3,
        VarbitID.TFA_CLIENT_P4, VarbitID.TFA_CLIENT_P5,
        VarbitID.TFA_CLIENT_P6, VarbitID.TFA_CLIENT_P7
    };

    private RaidPartyRoster()
    {
    }

    static List<String> readNames(Widget widget)
    {
        if (widget == null || widget.isHidden())
        {
            return null;
        }
        List<String> names = new ArrayList<>();
        Set<Widget> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        readNames(widget, names, visited);
        return names.isEmpty() ? null : names;
    }

    private static void readNames(Widget widget, List<String> names, Set<Widget> visited)
    {
        if (widget == null || widget.isHidden() || !visited.add(widget))
        {
            return;
        }
        if (widget.getType() == WidgetType.TEXT && widget.getText() != null)
        {
            Collections.addAll(names, widget.getText().split("(?i)<br>|\\r?\\n", -1));
        }
        readChildren(widget.getStaticChildren(), names, visited);
        readChildren(widget.getDynamicChildren(), names, visited);
        readChildren(widget.getNestedChildren(), names, visited);
    }

    private static void readChildren(Widget[] children, List<String> names, Set<Widget> visited)
    {
        if (children != null)
        {
            for (Widget child : children)
            {
                readNames(child, names, visited);
            }
        }
    }
}

package com.extendedignorelist;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.awt.Component;
import java.util.Arrays;
import java.util.Collections;
import java.util.Deque;
import java.util.ArrayDeque;
import java.util.IdentityHashMap;
import java.util.List;
import java.util.Set;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicReference;
import java.util.concurrent.atomic.AtomicBoolean;
import java.awt.Container;
import java.awt.event.MouseEvent;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingUtilities;
import org.junit.Test;

public class ExtendedIgnoreListPanelTest
{
    @Test
    public void rendersPlayerRowsAndAliases() throws Exception
    {
        AtomicInteger importClicks = new AtomicInteger();
        AtomicReference<String> removedPlayer = new AtomicReference<>();
        ExtendedIgnoreListPanel panel = new ExtendedIgnoreListPanel(importClicks::incrementAndGet,
            removedPlayer::set, (ignored, note) -> { }, IgnoreListSortOrder.NEWEST_FIRST, ignored -> { });

        List<IgnoredPlayer> players = Arrays.asList(
            new IgnoredPlayer("Alice", Collections.singletonList("Alicia")),
            new IgnoredPlayer("Bob")
        );

        SwingUtilities.invokeAndWait(() -> panel.setPlayers(players));

        assertTrue(findLabelText(panel, "Alice"));
        assertTrue(findLabelText(panel, "\u21C4"));
        assertTrue(findLabelText(panel, "Bob"));
        assertFalse(findLabelText(panel, "No players added yet."));
    }

    @Test
    public void rowClickInvokesCallbackWithCurrentName() throws Exception
    {
        AtomicReference<String> removedPlayer = new AtomicReference<>();
        ExtendedIgnoreListPanel panel = new ExtendedIgnoreListPanel(() -> { }, removedPlayer::set,
            (ignored, note) -> { }, IgnoreListSortOrder.NEWEST_FIRST, ignored -> { });
        SwingUtilities.invokeAndWait(() -> panel.setPlayers(Collections.singletonList(new IgnoredPlayer("Charlie"))));

        JLabel nameLabel = findLabel(panel, "Charlie");
        JPanel rowPanel = (JPanel) nameLabel.getParent().getParent();
        assertEquals(null, rowPanel.getToolTipText());

        SwingUtilities.invokeAndWait(() -> rowPanel.dispatchEvent(
            new MouseEvent(
                rowPanel,
                MouseEvent.MOUSE_CLICKED,
                System.currentTimeMillis(),
                0,
                4,
                4,
                1,
                false,
                MouseEvent.BUTTON1
            )
        ));
        assertEquals("Charlie", removedPlayer.get());
    }

    @Test
    public void importButtonStateReflectsAvailability() throws Exception
    {
        AtomicReference<ExtendedIgnoreListPanel> panelRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> panelRef.set(new ExtendedIgnoreListPanel(() -> { }, ignored -> { },
            (ignored, note) -> { }, IgnoreListSortOrder.NEWEST_FIRST, ignored -> { })));
        ExtendedIgnoreListPanel panel = panelRef.get();
        JButton importButton = findButton(panel, "Import ignore list");

        AtomicBoolean disabledByDefault = new AtomicBoolean();
        SwingUtilities.invokeAndWait(() -> disabledByDefault.set(!importButton.isEnabled()));
        assertTrue(disabledByDefault.get());

        SwingUtilities.invokeAndWait(() -> panel.setImportButtonState(true, null));
        assertTrue(importButton.isEnabled());
        assertEquals(null, importButton.getToolTipText());

        SwingUtilities.invokeAndWait(() -> panel.setImportButtonState(false, "No new native ignore list entries to import."));
        assertFalse(importButton.isEnabled());
        assertEquals("No new native ignore list entries to import.", importButton.getToolTipText());
    }

    @Test
    public void notedRowsShowNoteIndicatorAndInteractionHelp() throws Exception
    {
        ExtendedIgnoreListPanel panel = new ExtendedIgnoreListPanel(() -> { }, ignored -> { },
            (ignored, note) -> { }, IgnoreListSortOrder.NEWEST_FIRST, ignored -> { });
        IgnoredPlayer player = new IgnoredPlayer("Dana");
        player.setNote("Follow up later");

        SwingUtilities.invokeAndWait(() -> panel.setPlayers(Collections.singletonList(player)));

        assertTrue(findLabelText(panel, "\u25A4"));
        assertTrue(findLabelText(panel, "Left-click: delete"));
        assertTrue(findLabelText(panel, "Right-click: edit note"));
        Container helpPanel = findLabel(panel, "Right-click: edit note").getParent();
        Container sortPanel = findSortSelector(panel).getParent();
        Container topPanel = helpPanel.getParent();
        assertEquals(topPanel, sortPanel.getParent());
        assertTrue(topPanel.getComponentZOrder(helpPanel) < topPanel.getComponentZOrder(sortPanel));
    }

    @Test
    public void sortSelectorRestoresSelectionAndOnlyNotifiesForUserChanges() throws Exception
    {
        AtomicReference<IgnoreListSortOrder> selected = new AtomicReference<>();
        AtomicReference<ExtendedIgnoreListPanel> panelRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> panelRef.set(new ExtendedIgnoreListPanel(
            () -> { }, ignored -> { }, (ignored, note) -> { },
            IgnoreListSortOrder.NAME_DESCENDING, selected::set)));
        ExtendedIgnoreListPanel panel = panelRef.get();
        JComboBox<?> selector = findSortSelector(panel);
        assertEquals(4, selector.getItemCount());
        assertEquals(IgnoreListSortOrder.NAME_DESCENDING, selector.getSelectedItem());
        assertEquals(null, selected.get());

        SwingUtilities.invokeAndWait(() -> selector.setSelectedItem(IgnoreListSortOrder.OLDEST_FIRST));
        assertEquals(IgnoreListSortOrder.OLDEST_FIRST, selected.get());

        selected.set(null);
        panel.setSortOrder(IgnoreListSortOrder.NEWEST_FIRST);
        SwingUtilities.invokeAndWait(() -> { });
        assertEquals(IgnoreListSortOrder.NEWEST_FIRST, selector.getSelectedItem());
        assertEquals(null, selected.get());
    }

    private JComboBox<?> findSortSelector(Container container)
    {
        for (Component child : container.getComponents())
        {
            if (child instanceof JComboBox)
            {
                return (JComboBox<?>) child;
            }
            if (child instanceof Container)
            {
                JComboBox<?> selector = findSortSelector((Container) child);
                if (selector != null)
                {
                    return selector;
                }
            }
        }
        return null;
    }

    @Test
    public void developerControlsAreAbsentByDefaultAndRequestClearWhenAdded() throws Exception
    {
        AtomicInteger clearRequests = new AtomicInteger();
        AtomicReference<ExtendedIgnoreListPanel> panelRef = new AtomicReference<>();
        SwingUtilities.invokeAndWait(() -> panelRef.set(new ExtendedIgnoreListPanel(
            () -> { }, ignored -> { }, (ignored, note) -> { },
            IgnoreListSortOrder.NEWEST_FIRST, ignored -> { })));
        ExtendedIgnoreListPanel panel = panelRef.get();
        assertEquals(java.awt.BorderLayout.class, panel.getLayout().getClass());
        assertEquals(null, ((java.awt.BorderLayout) panel.getLayout()).getLayoutComponent(
            java.awt.BorderLayout.SOUTH));
        SwingUtilities.invokeAndWait(() ->
        {
            panel.addDeveloperControls(clearRequests::incrementAndGet);
            JButton importButton = findButton(panel, "Import ignore list");
            JButton clearButton = findButton(panel, "Clear extended list (dev)");
            Container topPanel = importButton.getParent();
            assertEquals(topPanel, clearButton.getParent());
            assertEquals(topPanel.getComponentZOrder(importButton) + 2,
                topPanel.getComponentZOrder(clearButton));
            clearButton.doClick();
        });
        assertEquals(1, clearRequests.get());
    }

    private boolean findLabelText(Component component, String text)
    {
        if (component instanceof JLabel && text.equals(((JLabel) component).getText()))
        {
            return true;
        }

        if (component instanceof Container)
        {
            for (Component child : ((Container) component).getComponents())
            {
                if (findLabelText(child, text))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private JLabel findLabel(Component component, String text)
    {
        Deque<Component> queue = new ArrayDeque<>();
        Set<Component> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        queue.add(component);

        while (!queue.isEmpty())
        {
            Component current = queue.removeFirst();
            if (!visited.add(current))
            {
                continue;
            }

            if (current instanceof JLabel && text.equals(((JLabel) current).getText()))
            {
                return (JLabel) current;
            }

            if (current instanceof Container)
            {
                for (Component child : ((Container) current).getComponents())
                {
                    queue.addLast(child);
                }
            }
        }

        throw new AssertionError("Label not found: " + text);
    }

    private JButton findButton(Component component, String text)
    {
        Deque<Component> queue = new ArrayDeque<>();
        Set<Component> visited = Collections.newSetFromMap(new IdentityHashMap<>());
        queue.add(component);

        while (!queue.isEmpty())
        {
            Component current = queue.removeFirst();
            if (!visited.add(current))
            {
                continue;
            }

            if (current instanceof JButton && text.equals(((JButton) current).getText()))
            {
                return (JButton) current;
            }

            if (current instanceof Container)
            {
                for (Component child : ((Container) current).getComponents())
                {
                    queue.addLast(child);
                }
            }
        }

        throw new AssertionError("Button not found: " + text);
    }

    private JButton findButton(ExtendedIgnoreListPanel panel, String text)
    {
        return findButton((Component) panel, text);
    }
}

